describe('Bulk Delete Items from List', () => {
    beforeEach(() => {
        cy.visit('/items'); // Adjust the URL to the actual page where the items are listed
    });

    it('should successfully bulk delete selected items', () => {
        // Select items to delete
        cy.get('.item-checkbox').first().check();
        cy.get('.item-checkbox').eq(1).check();

        // Click on the bulk delete button
        cy.get('.bulk-delete-button').click();

        // Confirm the deletion
        cy.get('.confirm-delete-button').click();

        // Verify items are deleted
        cy.get('.item-list').should('not.contain', 'Item 1'); // Adjust based on actual item names
        cy.get('.item-list').should('not.contain', 'Item 2'); // Adjust based on actual item names
    });

    it('should show an error message when no items are selected for deletion', () => {
        // Click on the bulk delete button without selecting any items
        cy.get('.bulk-delete-button').click();

        // Verify the error message is displayed
        cy.get('.error-message').should('be.visible').and('contain', 'No items selected for deletion');
    });
});
